.hc { position: relative; }

/* Os slides ocupam a MESMA célula: a altura é a do mais alto, e a seção não
   muda de tamanho na troca. Com position:absolute seria preciso altura fixa. */
.hc-palco { display: grid; }
.hc-slide {
  grid-area: 1 / 1;
  position: relative;
  min-height: 420px;
  opacity: 0;
  transition: opacity 1s ease;
  pointer-events: none;
}
.hc-ativo { opacity: 1; pointer-events: auto; }

.hc-foto { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }

/* Piso de contraste na coluna do texto, sem escurecer a foto inteira. */
.hc-veu {
  position: absolute; inset: 0;
  background: linear-gradient(to right, rgba(0,0,0,0.92), rgba(0,0,0,0.75) 45%, rgba(0,0,0,0.25));
}

.hc-texto {
  position: relative;
  max-width: 620px;
  padding: 72px 40px;
}
.hc-eyebrow {
  margin: 0 0 12px;
  font-family: 'JetBrains Mono', monospace; font-size: 11px;
  letter-spacing: 0.14em; text-transform: uppercase; color: var(--accent);
}
.hc-titulo {
  margin: 0 0 16px;
  font-family: 'Sora', sans-serif; font-weight: 700;
  font-size: clamp(28px, 4vw, 44px); line-height: 1.1; letter-spacing: -0.02em;
}
.hc-desc { margin: 0 0 24px; max-width: 46ch; color: var(--text-muted); line-height: 1.6; }
.hc-btn {
  display: inline-block; padding: 14px 26px; border-radius: 4px;
  background: var(--accent); color: var(--bg); font-weight: 600; font-size: 14px;
}

.hc-dots { position: absolute; left: 40px; bottom: 28px; display: flex; gap: 8px; }
.hc-dot {
  width: 44px; height: 3px; padding: 0; border: none; cursor: pointer;
  background: rgba(255,255,255,0.25); overflow: hidden;
}
/* A barra é o relógio do autoplay: ela é animada pela Web Animations API com
   a MESMA duração do intervalo, então não existe segundo contador pra
   dessincronizar. */
.hc-bar { display: block; height: 100%; width: 0; background: #fff; }

@media (max-width: 640px) {
  .hc-texto { padding: 56px 24px; }
  .hc-dots { left: 24px; }
}

