const INTERVALO = 5000

export function iniciarHero(raiz) {
  const slides = [...raiz.querySelectorAll('.hc-slide')]
  const dots = raiz.querySelector('.hc-dots')
  let atual = 0
  let timer = null

  // Nem background-image nem <img> em container invisível respeitam o lazy do
  // navegador: sem pintar sob demanda, todas as fotos baixam no primeiro paint.
  function pintar(i) {
    const img = slides[i % slides.length]?.querySelector('.hc-foto')
    if (img && img.dataset.src) {
      img.src = img.dataset.src
      delete img.dataset.src
    }
  }

  slides.forEach((_, i) => {
    const botao = document.createElement('button')
    botao.type = 'button'
    botao.className = 'hc-dot'
    botao.setAttribute('aria-label', `Destaque ${i + 1}`)
    botao.innerHTML = '<span class="hc-bar"></span>'
    botao.addEventListener('click', () => ir(i))
    dots.appendChild(botao)
  })

  const barras = [...dots.querySelectorAll('.hc-bar')]

  function ir(i) {
    atual = (i + slides.length) % slides.length
    pintar(atual)
    pintar(atual + 1)

    slides.forEach((s, n) => {
      const ligado = n === atual
      s.classList.toggle('hc-ativo', ligado)
      // Slide invisível não pode receber Tab: o foco sumiria da tela.
      if (ligado) s.removeAttribute('inert')
      else s.setAttribute('inert', '')
    })

    dots.querySelectorAll('.hc-dot').forEach((d, n) => {
      if (n === atual) d.setAttribute('aria-current', 'true')
      else d.removeAttribute('aria-current')
    })

    barras.forEach((b) => b.getAnimations().forEach((a) => a.cancel()))
    if (timer) {
      barras[atual].animate([{ width: '0%' }, { width: '100%' }], {
        duration: INTERVALO,
        easing: 'linear',
        fill: 'forwards',
      })
    }
  }

  function tocar() {
    if (timer) return
    timer = window.setInterval(() => ir(atual + 1), INTERVALO)
    ir(atual)
  }
  function pausar() {
    window.clearInterval(timer)
    timer = null
    barras.forEach((b) => b.getAnimations().forEach((a) => a.pause()))
  }

  raiz.addEventListener('mouseenter', pausar)
  raiz.addEventListener('focusin', pausar)
  raiz.addEventListener('mouseleave', tocar)
  raiz.addEventListener('focusout', tocar)

  // Arraste horizontal maior que 50px troca de slide.
  let x0 = null
  raiz.addEventListener('touchstart', (e) => { x0 = e.touches[0].clientX }, { passive: true })
  raiz.addEventListener('touchend', (e) => {
    if (x0 === null) return
    const d = e.changedTouches[0].clientX - x0
    if (Math.abs(d) > 50) ir(atual + (d < 0 ? 1 : -1))
    x0 = null
  }, { passive: true })

  ir(0)
  if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) tocar()
}
